const AWS = require('aws-sdk');
const AdmZip = require('adm-zip');
const path = require('path');
const fs = require('fs');
const os = require('os');

const s3 = new AWS.S3();

/**
 * Lambda handler that processes uploaded ZIP archives from S3.
 * Extracts contents to /tmp for further processing (e.g., thumbnail generation).
 * 
 * Event shape: { bucket: string, key: string }
 */
exports.handler = async (event) => {
  const { bucket, key } = event;

  if (!bucket || !key) {
    return { statusCode: 400, body: 'Missing bucket or key' };
  }

  // Validate file extension
  if (!key.endsWith('.zip')) {
    return { statusCode: 400, body: 'Only .zip files are accepted' };
  }

  const tmpDir = path.join(os.tmpdir(), `extract_${Date.now()}`);
  fs.mkdirSync(tmpDir, { recursive: true });

  try {
    // Download ZIP from S3
    const s3Object = await s3.getObject({ Bucket: bucket, Key: key }).promise();
    const zipPath = path.join(os.tmpdir(), `download_${Date.now()}.zip`);
    fs.writeFileSync(zipPath, s3Object.Body);

    // Extract ZIP contents
    const zip = new AdmZip(zipPath);
    const entries = zip.getEntries();

    const extractedFiles = [];

    for (const entry of entries) {
      if (entry.isDirectory) continue;

      // Construct output path from entry name
      const outputPath = path.join(tmpDir, entry.entryName);

      // Create parent directories if needed
      const parentDir = path.dirname(outputPath);
      fs.mkdirSync(parentDir, { recursive: true });

      // Write file content
      fs.writeFileSync(outputPath, entry.getData());
      extractedFiles.push(outputPath);
    }

    // Process extracted files (e.g., generate thumbnails, scan content)
    const results = await processFiles(extractedFiles);

    // Cleanup
    fs.unlinkSync(zipPath);

    return {
      statusCode: 200,
      body: JSON.stringify({
        message: `Processed ${extractedFiles.length} files`,
        results
      })
    };
  } catch (err) {
    console.error('Processing error:', err);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: err.message })
    };
  }
};

async function processFiles(files) {
  const results = [];
  for (const file of files) {
    const stat = fs.statSync(file);
    results.push({
      path: file,
      size: stat.size,
      processed: true
    });
  }
  return results;
}

/**
 * Utility: validate content type header from API Gateway proxy event
 * Used when this Lambda is behind API Gateway for direct uploads
 */
exports.validateUpload = (headers) => {
  const contentType = headers['content-type'] || headers['Content-Type'];
  if (!contentType || !contentType.includes('multipart/form-data')) {
    throw new Error('Invalid content type for upload');
  }
  return true;
};

/**
 * Health check endpoint
 */
exports.health = async () => {
  return { statusCode: 200, body: JSON.stringify({ status: 'ok', version: '2.1.4' }) };
};
